package com.gazellio.platform.controller; import com.gazellio.platform.dto.ApiDtos.*; import com.gazellio.platform.service.ApprovalService; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import org.springframework.security.access.prepost.PreAuthorize; import java.util.*;
@RestController @RequestMapping("/api/approvals") @RequiredArgsConstructor public class ApprovalController {private final ApprovalService service;@GetMapping public List<ApprovalView> list(){return service.list();}@GetMapping("/{id}") public ApprovalView get(@PathVariable Long id){return service.get(id);}@PreAuthorize("hasAnyRole('APPROVER','ADMIN')") @PostMapping("/{id}/approve") public ApprovalView approve(@PathVariable Long id,@RequestBody(required=false) ApprovalActionRequest req){return service.approve(id,req);}@PreAuthorize("hasAnyRole('APPROVER','ADMIN')") @PostMapping("/{id}/reject") public ApprovalView reject(@PathVariable Long id,@RequestBody(required=false) ApprovalActionRequest req){return service.reject(id,req);}}
